nta.declaration:
// NR RRC intra-NR handover (reconfiguration with sync), TS 38.331.
// Clauses modelled:
//   5.3.5.5.2  RRCReconfiguration with reconfigurationWithSync received:
//              if AS security is not activated, go to RRC_IDLE ('other');
//              else stop T310, start T304, sync to the target SpCell
//   5.3.5.8.3  T304 expiry = reconfiguration with sync failure:
//              revert to the source PCell configuration, store the
//              handover failure information in VarRLF-Report, initiate
//              connection re-establishment as specified in 5.3.7
//   5.3.7.2-7  re-establishment chain: T311 / cell selection / T301 /
//              RRCReestablishmentRequest / RRCReestablishment or idle
//   5.3.7.4    re-establishment initiated due to reconfiguration with sync
//              failure -> reestablishmentCause = handoverFailure,
//              c-RNTI and physCellId of the source PCell
// Abstractions (documented on the site):
//   - AS security is activated, so the reconfigurationWithSync is accepted
//     (the spec's not-activated branch is kept as a guarded, disabled edge)
//   - random access to the target either succeeds within T304 or the
//     timer expires; the target's response is nondeterministic
//   - the source gNB commands the handover at t=0 (forced first event)

const int T304 = 4;
const int T311 = 5;
const int T301 = 3;
const int SEC_ACTIVATED = 1;
const int RA_BUDGET = 1;
const int CELL_BUDGET = 1;

int ra_left = RA_BUDGET;
int cell_left = CELL_BUDGET;

// handover outcome bookkeeping
int ho_completed = 0;
int hf_report = 0;
int reest_ok = 0;
int went_idle = 0;

clock t304;
clock t311;
clock t301;

chan ho_cmd;
chan ra_success;
chan cell_found;
chan rr_ok;
chan rr_reject;

nta.system:
UE = UE();
Src = Src();
Tgt = Tgt();
Net = Net();
system UE, Src, Tgt, Net;
